(6670699, 997648, 73942, '<td valign="top">nice processing</td>', 'nice processing', '2012-02-10 20:20:42.000000', NULL, 1),
(6670701, 997548, 76335, '<td valign="top">A different portrait of Iceland than we''re used to seeing. Are these wild horses? This is excellent.</td>', 'A different portrait of Iceland than we''re used to seeing. Are these wild horses? This is excellent.', '2012-02-10 20:21:16.000000', NULL, 1),
(6670702, 997217, 23484, '<td valign="top">Cool lines.</td>', 'Cool lines.', '2012-02-10 20:21:35.000000', NULL, 1),
