(6670722, 993598, 23484, '<td valign="top">Nice job on the processing.</td>', 'Nice job on the processing.', '2012-02-10 20:26:51.000000', NULL, 1),
(6670723, 995125, 76335, '<td valign="top">Unglamorous and unsettling. The lo-fi feel of the image further drives the point home. Good.</td>', 'Unglamorous and unsettling. The lo-fi feel of the image further drives the point home. Good.', '2012-02-10 20:27:12.000000', NULL, 1),
(6670725, 997842, 23484, '<td valign="top">This is really neat.</td>', 'This is really neat.', '2012-02-10 20:27:49.000000', NULL, 1),
(6670726, 994609, 76335, '<td valign="top">What cooperative clouds you have.</td>', 'What cooperative clouds you have.', '2012-02-10 20:27:51.000000', NULL, 1),
(6670727, 997469, 23484, '<td valign="top">Wow, great catch.</td>', 'Wow, great catch.', '2012-02-10 20:28:02.000000', NULL, 1),
(6670728, 993606, 76335, '<td valign="top">Up close, honest and intimate. I like the softness. The moment between moments.</td>', 'Up close, honest and intimate. I like the softness. The moment between moments.', '2012-02-10 20:28:40.000000', NULL, 1),
(6670729, 994471, 76335, '<td valign="top">Entirely too funny.</td>', 'Entirely too funny.', '2012-02-10 20:29:35.000000', NULL, 1),
(6670730, 994809, 124815, '<td valign="top">I can feel the wind and cold that chiseled this face but how the smile remained it''s a mystery only this woman knows.</td>', 'I can feel the wind and cold that chiseled this face but how the smile remained it''s a mystery only this woman knows.', '2012-02-10 20:29:43.000000', NULL, 1),
(6670731, 997795, 76335, '<td valign="top">Quirky. Takes a second to register as the flesh of the child seems as smooth as the plastic of the figure. Fun.</td>', 'Quirky. Takes a second to register as the flesh of the child seems as smooth as the plastic of the figure. Fun.', '2012-02-10 20:30:50.000000', NULL, 1),
(6670732, 998200, 73942, '<td valign="top">love the tonal map and the sharpness all the way thru</td>', 'love the tonal map and the sharpness all the way thru', '2012-02-10 20:31:02.000000', NULL, 1),
(6670734, 994762, 76335, '<td valign="top">A four color landscape. And, oh, THANK YOU for not cloning out the pylons. They are the composition.</td>', 'A four color landscape. And, oh, THANK YOU for not cloning out the pylons. They are the composition.', '2012-02-10 20:31:39.000000', NULL, 1),
(6670735, 994157, 124815, '<td valign="top">If there was ever a "croise" in ballet ....</td>', 'If there was ever a "croise" in ballet ....', '2012-02-10 20:32:13.000000', NULL, 1),
