(6670738, 997880, 76335, '<td valign="top">A piercing, honest gaze. The background complements this nicely.</td>', 'A piercing, honest gaze. The background complements this nicely.', '2012-02-10 20:33:12.000000', NULL, 1),
(6670740, 997836, 76335, '<td valign="top">The hat and hair seem to dance and swirl around each other. They embrace her face nicely.</td>', 'The hat and hair seem to dance and swirl around each other. They embrace her face nicely.', '2012-02-10 20:34:16.000000', NULL, 1),
