INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6672048, 996974, 94265, '<td valign="top">Very well captured, focus and composition are great despite the clearly candid moment. Hope the rider was Ok, looks like it could have been a sore one, the poor horse looks scared to death. Excellent shot all round.</td>', 'Very well captured, focus and composition are great despite the clearly candid moment. Hope the rider was Ok, looks like it could have been a sore one, the poor horse looks scared to death. Excellent shot all round.', '2012-02-11 22:01:41.000000', NULL, 1),
(6672049, 994730, 30982, '<td valign="top">Very good composition, great light on your subject.</td>', 'Very good composition, great light on your subject.', '2012-02-11 22:02:01.000000', NULL, 1),
(6672050, 997677, 30982, '<td valign="top">Shows off her eyes very well - and they''re lovely!</td>', 'Shows off her eyes very well - and they''re lovely!', '2012-02-11 22:02:34.000000', NULL, 1),
(6672054, 995909, 94265, '<td valign="top">What an odd-looking and interesting tree, the b&amp;w really makes all the hanging foliage stand out and gives the photo an appealing feeling of strangeness. I think it would have been cool in colour too, mind. Very nice.</td>', 'What an odd-looking and interesting tree, the b&w really makes all the hanging foliage stand out and gives the photo an appealing feeling of strangeness. I think it would have been cool in colour too, mind. Very nice.', '2012-02-11 22:04:36.000000', NULL, 1),
(6672056, 997757, 94265, '<td valign="top">A nice vantage point and but the noise in this image is majorly strong, a good denoising would have helped this shot along.</td>', 'A nice vantage point and but the noise in this image is majorly strong, a good denoising would have helped this shot along.', '2012-02-11 22:05:44.000000', NULL, 1),
(6672058, 998045, 30982, '<td valign="top">Marvelous sweep of color.  Make sure you put this in a calendar if you make one!</td>', 'Marvelous sweep of color.  Make sure you put this in a calendar if you make one!', '2012-02-11 22:07:56.000000', NULL, 1),
