(6675726, 997767, 119012, '<td valign="top">too soft, horizon looks crooked.</td>', 'too soft, horizon looks crooked.', '2012-02-14 07:36:34.000000', NULL, 1),
(6675727, 996531, 76335, '<td valign="top">Soft and simply stated. Calming. I keep coming back to it.</td>', 'Soft and simply stated. Calming. I keep coming back to it.', '2012-02-14 07:36:47.000000', NULL, 1),
(6675728, 994157, 25787, '<td valign="top">Black and white done beautifully.</td>', 'Black and white done beautifully.', '2012-02-14 07:37:00.000000', NULL, 1),
