(6675885, 995665, 129807, '<td valign="top">Surreal colours - almost glowing internally. Looks maybe a tad oversharpened.</td>', 'Surreal colours - almost glowing internally. Looks maybe a tad oversharpened.', '2012-02-14 08:50:36.000000', NULL, 1),
(6675888, 997451, 129807, '<td valign="top">Oh, those eyes!</td>', 'Oh, those eyes!', '2012-02-14 08:51:07.000000', NULL, 1),
