(6676047, 997874, 114233, '<td valign="top">I wont ding you for the sensor dust left of the tower or the one in the middle top of the bean.<br/>Nice comp and leading lines. Not a fan of this heavy HDR but it kind of works on this shot.</td>', 'I wont ding you for the sensor dust left of the tower or the one in the middle top of the bean.Nice comp and leading lines. Not a fan of this heavy HDR but it kind of works on this shot.', '2012-02-14 09:57:50.000000', NULL, 1),
(6676048, 994338, 129807, '<td valign="top">Simple. Elegant. Beautiful.</td>', 'Simple. Elegant. Beautiful.', '2012-02-14 09:58:05.000000', NULL, 1),
(6676049, 997976, 49773, '<td valign="top">Lovely metaphore.</td>', 'Lovely metaphore.', '2012-02-14 09:58:26.000000', NULL, 1),
(6676052, 998065, 101668, '<td valign="top">moonflowers? Lovely shot</td>', 'moonflowers? Lovely shot', '2012-02-14 09:59:32.000000', NULL, 1),
(6676053, 996742, 114233, '<td valign="top">I know you tried to get the verticals straight on the life guard tower but the horizon looks very skew to me (down on the left). Lovely image tho and the leading lines work a treat on this shot</td>', 'I know you tried to get the verticals straight on the life guard tower but the horizon looks very skew to me (down on the left). Lovely image tho and the leading lines work a treat on this shot', '2012-02-14 09:59:43.000000', NULL, 1),
