(6678197, 996902, 96751, '<td valign="top">Great astrophotography</td>', 'Great astrophotography', '2012-02-15 16:08:22.000000', NULL, 1),
(6678199, 995056, 96751, '<td valign="top">Magical lighting.  Beautiful, evocative image - is she asleep.  Is she dead...</td>', 'Magical lighting.  Beautiful, evocative image - is she asleep.  Is she dead...', '2012-02-15 16:09:09.000000', NULL, 1),
(6678200, 995245, 96751, '<td valign="top">This image takes a moment to register.  I''m first drawn to the dancers in white, who seem to be tottering and not all that graceful.  Then my eye travels across the scene to discover the tiny ballerina.  Wonderful</td>', 'This image takes a moment to register.  I''m first drawn to the dancers in white, who seem to be tottering and not all that graceful.  Then my eye travels across the scene to discover the tiny ballerina.  Wonderful', '2012-02-15 16:09:33.000000', NULL, 1),
(6678293, 998066, 25773, '<td valign="top">I wish I saw the eyes open... chances are the nice baby-blue eyes would have matched nicely with the surrounding</td>', 'I wish I saw the eyes open... chances are the nice baby-blue eyes would have matched nicely with the surrounding', '2012-02-15 17:50:42.000000', NULL, 1),
(6678306, 997648, 25773, '<td valign="top">Looks real cool. I might have preferred a tad bit of stronger contrast, but the details and DR (HDR?) are outstanding.</td>', 'Looks real cool. I might have preferred a tad bit of stronger contrast, but the details and DR (HDR?) are outstanding.', '2012-02-15 17:59:46.000000', NULL, 1),
(6678347, 994058, 111032, '<td valign="top">would have been great with a little more detail in the bee and flower.</td>', 'would have been great with a little more detail in the bee and flower.', '2012-02-15 18:22:54.000000', NULL, 1),
