(6678454, 998188, 142473, '<td valign="top">Really nice image.  I think I would have cropped off a little from the bottom though.</td>', 'Really nice image.  I think I would have cropped off a little from the bottom though.', '2012-02-15 19:42:53.000000', NULL, 1),
(6678457, 995676, 142473, '<td valign="top">Not your everyday cat photo.  Actually very nice.  The back lighting works really well.</td>', 'Not your everyday cat photo.  Actually very nice.  The back lighting works really well.', '2012-02-15 19:44:16.000000', NULL, 1),
(6678458, 997805, 142473, '<td valign="top">Dang nice photo.  The big lighted area on the left makes it.</td>', 'Dang nice photo.  The big lighted area on the left makes it.', '2012-02-15 19:45:43.000000', NULL, 1),
