(6678626, 998188, 114225, '<td valign="top">I really enjoy the color pallet that makes up tho image.</td>', 'I really enjoy the color pallet that makes up tho image.', '2012-02-15 22:33:21.000000', NULL, 1),
(6678627, 997912, 38032, '<td valign="top">lovely classic feel. Very sexy and confident yet modest as well.</td>', 'lovely classic feel. Very sexy and confident yet modest as well.', '2012-02-15 22:33:30.000000', NULL, 1),
(6678628, 994078, 114225, '<td valign="top">Amazing spectrum of light.</td>', 'Amazing spectrum of light.', '2012-02-15 22:33:40.000000', NULL, 1),
