(6679761, 993604, 11854, '<td valign="top">Wow. Did you hold up a sign saying stop? LOL! Great catch.</td>', 'Wow. Did you hold up a sign saying stop? LOL! Great catch.', '2012-02-16 17:10:00.000000', NULL, 1),
(6679762, 995245, 11854, '<td valign="top">This is just too cute for words. Love it!</td>', 'This is just too cute for words. Love it!', '2012-02-16 17:10:22.000000', NULL, 1),
