(6681643, 997863, 77196, '<td valign="top">Wonderful silhouette of both the bicyclist and Haystack Rock. Love the look of the wet sand, reflecting the sunset sky.</td>', 'Wonderful silhouette of both the bicyclist and Haystack Rock. Love the look of the wet sand, reflecting the sunset sky.', '2012-02-17 23:30:30.000000', NULL, 1),
(6681644, 996061, 77196, '<td valign="top">Very nice skyline. Love the searchlights lighting up the night sky.</td>', 'Very nice skyline. Love the searchlights lighting up the night sky.', '2012-02-17 23:31:10.000000', NULL, 1),
(6681645, 994269, 77196, '<td valign="top">No words. Wonderful colors, interesting silhouettes, nice illumination of the water, and incredible light-painted grasses.</td>', 'No words. Wonderful colors, interesting silhouettes, nice illumination of the water, and incredible light-painted grasses.', '2012-02-17 23:32:22.000000', NULL, 1),
