INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6681812, 997677, 119419, '<td valign="top">Lighting is good, lovely capture.</td>', 'Lighting is good, lovely capture.', '2012-02-18 01:48:32.000000', NULL, 1),
