(6681913, 995223, 19825, '<td valign="top">I love the colors and the contrast.</td>', 'I love the colors and the contrast.', '2012-02-18 08:08:55.000000', NULL, 1),
(6681914, 997676, 19825, '<td valign="top">Stark beauty.</td>', 'Stark beauty.', '2012-02-18 08:10:12.000000', NULL, 1),
