(6681938, 994628, 19825, '<td valign="top">Wonderful character in her face, but that stare makes the shot. Great capture, Lev.</td>', 'Wonderful character in her face, but that stare makes the shot. Great capture, Lev.', '2012-02-18 08:59:37.000000', NULL, 1),
(6681943, 997061, 11854, '<td valign="top">Beautiful shape and form!</td>', 'Beautiful shape and form!', '2012-02-18 09:29:53.000000', NULL, 1),
