(6681946, 995850, 11854, '<td valign="top">What a pretty place for a walk!</td>', 'What a pretty place for a walk!', '2012-02-18 09:31:35.000000', NULL, 1),
(6681947, 994053, 11854, '<td valign="top">Looks like he''s coming for you! LOL!</td>', 'Looks like he''s coming for you! LOL!', '2012-02-18 09:32:08.000000', NULL, 1),
