(6681949, 996566, 14867, '<td valign="top">Sublime light, natural and moving portraits. In my top 3 for the challenge.</td>', 'Sublime light, natural and moving portraits. In my top 3 for the challenge.', '2012-02-18 09:32:34.000000', NULL, 1),
(6681950, 996067, 11854, '<td valign="top">It looks like they''re trying to form a pattern. Maybe spell out HELP, but they don''t know how to spell. ;D</td>', 'It looks like they''re trying to form a pattern. Maybe spell out HELP, but they don''t know how to spell. ;D', '2012-02-18 09:33:36.000000', NULL, 1),
(6681951, 996015, 14867, '<td valign="top">Funny - and also a very impressive macro, the management of the DOF is incredibly good !</td>', 'Funny - and also a very impressive macro, the management of the DOF is incredibly good !', '2012-02-18 09:33:53.000000', NULL, 1),
(6681952, 993908, 11854, '<td valign="top">How cute!</td>', 'How cute!', '2012-02-18 09:33:54.000000', NULL, 1),
(6681953, 997410, 14867, '<td valign="top">Classic, still a delight for the eye</td>', 'Classic, still a delight for the eye', '2012-02-18 09:34:32.000000', NULL, 1),
(6681954, 996488, 14867, '<td valign="top">Excellent, the DOF and the almost monochromatic background are making this image rather fascinating</td>', 'Excellent, the DOF and the almost monochromatic background are making this image rather fascinating', '2012-02-18 09:35:57.000000', NULL, 1),
(6681955, 996316, 14867, '<td valign="top">I like the unusual POV and the simple, well balanced composition. Not completely sure about the HDR-like postprocessing</td>', 'I like the unusual POV and the simple, well balanced composition. Not completely sure about the HDR-like postprocessing', '2012-02-18 09:37:35.000000', NULL, 1),
(6681965, 995627, 136235, '<td valign="top">Nice composition and subject matter though way too over-processed for my taste.</td>', 'Nice composition and subject matter though way too over-processed for my taste.', '2012-02-18 10:04:37.000000', NULL, 1),
