(6681967, 993793, 136235, '<td valign="top">I feel this composition would be more interesting if there were a bit more water and a bit less sky; nice tones in the buildings and sky though.</td>', 'I feel this composition would be more interesting if there were a bit more water and a bit less sky; nice tones in the buildings and sky though.', '2012-02-18 10:06:16.000000', NULL, 1),
(6681970, 997002, 136235, '<td valign="top">Great processing and detail!</td>', 'Great processing and detail!', '2012-02-18 10:07:36.000000', NULL, 1),
(6681972, 996986, 86799, '<td valign="top">Cool to see GBH in a non-fish-catching-non-flying-non-wading action.  Nice profile.</td>', 'Cool to see GBH in a non-fish-catching-non-flying-non-wading action.  Nice profile.', '2012-02-18 10:08:12.000000', NULL, 1),
(6681974, 996709, 136235, '<td valign="top">Very nice image with a very interesting subject; different from anything I''ve seen so far in the challenge. Nice job spotting this.</td>', 'Very nice image with a very interesting subject; different from anything I''ve seen so far in the challenge. Nice job spotting this.', '2012-02-18 10:09:46.000000', NULL, 1),
(6681975, 997693, 86799, '<td valign="top">Very charming and creative portrait.  Only the mis-directed attention of girl #2 makes it a little lopsided.  Otherwise, top notch!  Gotta bump it one.</td>', 'Very charming and creative portrait.  Only the mis-directed attention of girl #2 makes it a little lopsided.  Otherwise, top notch!  Gotta bump it one.', '2012-02-18 10:12:22.000000', NULL, 1),
(6681976, 997758, 136235, '<td valign="top">Very interesting subject and a well composed image, though this is a bit over-processed for my taste.</td>', 'Very interesting subject and a well composed image, though this is a bit over-processed for my taste.', '2012-02-18 10:12:54.000000', NULL, 1),
(6681985, 997759, 86799, '<td valign="top">Hola, amigo!  Excellent contrast of roughness and humor.  Gotta bump this up.</td>', 'Hola, amigo!  Excellent contrast of roughness and humor.  Gotta bump this up.', '2012-02-18 10:25:53.000000', NULL, 1),
(6681987, 995975, 86799, '<td valign="top">Excellent low humor.  One for the family album, to look back on when he''s 40!</td>', 'Excellent low humor.  One for the family album, to look back on when he''s 40!', '2012-02-18 10:27:46.000000', NULL, 1),
(6681993, 998107, 86799, '<td valign="top">Beautiful...so much to look at and enjoy...really draws in the viewer.</td>', 'Beautiful...so much to look at and enjoy...really draws in the viewer.', '2012-02-18 10:36:31.000000', NULL, 1),
(6681995, 997677, 86799, '<td valign="top">Smooooooth.  The flyaway hair is a very nice touch.</td>', 'Smooooooth.  The flyaway hair is a very nice touch.', '2012-02-18 10:38:45.000000', NULL, 1),
(6681998, 996148, 86799, '<td valign="top">Made me stop and follow, drawing me along to the far valley and beyond.  Great techs.</td>', 'Made me stop and follow, drawing me along to the far valley and beyond.  Great techs.', '2012-02-18 10:40:57.000000', NULL, 1),
(6682000, 994418, 86799, '<td valign="top">I see this LARGE, hanging in the lodge on the log wall, amongst the artifacts of the wild.  Lovely detail, color, contrast, composition.</td>', 'I see this LARGE, hanging in the lodge on the log wall, amongst the artifacts of the wild.  Lovely detail, color, contrast, composition.', '2012-02-18 10:43:32.000000', NULL, 1),
