INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6687852, 996889, 140305, '<td valign="top">Oh, this makes me wish for those warm summer days! Very pretty but I''m sure I would be in the bush :) Great shot.</td>', 'Oh, this makes me wish for those warm summer days! Very pretty but I''m sure I would be in the bush :) Great shot.', '2012-02-22 21:55:43.000000', NULL, 1),
(6687853, 996525, 140305, '<td valign="top">I think I just added this place to my bucket list as one of the places I have to see! Wow, how beautiful!</td>', 'I think I just added this place to my bucket list as one of the places I have to see! Wow, how beautiful!', '2012-02-22 21:59:10.000000', NULL, 1),
(6687857, 997409, 140305, '<td valign="top">You can dress them up but the dirt always finds them somehow! Really sweet photo that I''m sure a lot of parents can connect with.</td>', 'You can dress them up but the dirt always finds them somehow! Really sweet photo that I''m sure a lot of parents can connect with.', '2012-02-22 22:04:03.000000', NULL, 1),
(6687861, 997321, 140305, '<td valign="top">There is so much beauty in this world - my compliments on your ability to capture it so well. I can almost smell that clean mountain air.</td>', 'There is so much beauty in this world - my compliments on your ability to capture it so well. I can almost smell that clean mountain air.', '2012-02-22 22:07:16.000000', NULL, 1),
